draw.viewbox(0, 0, W, H);

var tokens = ['<start>', 'It', 'takes', 'great', 'courage', 'to', 'let'];
var targets = ['It', 'takes', 'great', 'courage', 'to', 'let', 'yourself'];
var n = 7;
var rowStart = 68;
var rowSp = 58;
function rowY(i) { return rowStart + i * rowSp; }

var COL = {
  orange: '#c07040', orangeLine: '#7a3b1a',
  teal: '#7ecfc0', tealStroke: '#3d9e8c',
  blue: '#a8c8dc', blueStroke: '#5a8faa',
  gray: '#d8d8d8', grayStroke: '#777',
  white: '#fff', black: '#222',
  highlight: '#ff5500', dim: '#ccc'
};

var gBg = draw.group();
var gTransformer = draw.group();
var gRight = draw.group();
var gOverlay = draw.group();

// ── Headers ──
var headerData = [
  { lines: ['Word', 'embeddings'], x: 112 },
  { lines: ['Transformer with', 'masked attention'], x: 345 },
  { lines: ['Linear +', 'softmax'], x: 640 },
  { lines: ['Probability of', 'target token'], x: 810 }
];
headerData.forEach(function(h) {
  h.lines.forEach(function(line, li) {
    gBg.text(line).attr({ x: h.x, y: 16 + li * 14, 'font-size': 12, 'font-family': 'sans-serif', 'text-anchor': 'middle', fill: COL.black, 'font-weight': 'bold' });
  });
});

// ── Input tokens + arrows + embedding boxes ──
var embGroup = gBg.group();
tokens.forEach(function(tok, i) {
  var y = rowY(i);
  embGroup.text(tok).attr({ x: 52, y: y + 5, 'font-size': 12, 'font-family': 'sans-serif', 'text-anchor': 'end', fill: COL.black });
  embGroup.line(56, y, 66, y).stroke({ color: COL.black, width: 1.2 });
  embGroup.polygon('66,' + (y - 3) + ' 72,' + y + ' 66,' + (y + 3)).fill(COL.black);
  // 6 embedding boxes
  for (var b = 0; b < 6; b++) {
    embGroup.rect(13, 16).attr({ x: 76 + b * 14, y: y - 8, fill: COL.white, stroke: COL.black, 'stroke-width': 0.8, rx: 1 });
  }
});
// Dashed container around embeddings
embGroup.rect(100, 380).attr({ x: 62, y: 48, fill: 'none', stroke: COL.grayStroke, 'stroke-width': 1.5, 'stroke-dasharray': '6,4', rx: 12 });

// ── Arrow from embeddings to transformer ──
var midY = rowY(3);
gBg.line(165, midY, 192, midY).stroke({ color: COL.black, width: 1.5 });
gBg.polygon('192,' + (midY - 4) + ' 200,' + midY + ' 192,' + (midY + 4)).fill(COL.black);

// ── Transformer block (drawn as function of K) ──
var tfX = 200, tfW = 290, tfY = 45, tfH = 395;

function drawTransformerBlock(k) {
  gTransformer.clear();
  // Gray dashed container
  gTransformer.rect(tfW, tfH).attr({ x: tfX, y: tfY, fill: COL.gray, stroke: COL.grayStroke, 'stroke-width': 2, 'stroke-dasharray': '8,5', rx: 14, opacity: 0.85 });

  var layerH = (tfH - 20) / k;
  for (var li = 0; li < k; li++) {
    var ly = tfY + 10 + li * layerH;
    var lh = layerH - 8;
    var cy = ly + lh / 2;

    // Mini attention matrix
    var amX = tfX + 15, amW = 80, amH = Math.min(lh - 4, 380);
    var amY = cy - amH / 2;
    gTransformer.rect(amW, amH).attr({ x: amX, y: amY, fill: COL.orange, stroke: COL.orangeLine, 'stroke-width': 1.5, rx: 6 });

    // Lower-triangular lines inside attention matrix
    var lineCount = Math.min(n, Math.max(3, Math.floor(amH / 12)));
    for (var i = 0; i < lineCount; i++) {
      for (var j = 0; j <= i; j++) {
        var y1 = amY + 4 + (amH - 8) * (i / (lineCount - 1));
        var y2 = amY + 4 + (amH - 8) * (j / (lineCount - 1));
        gTransformer.line(amX + 4, y1, amX + amW - 4, y2).stroke({ color: COL.orangeLine, width: 0.7, opacity: 0.7 });
      }
    }

    // First ⊕
    var plus1X = amX + amW + 22;
    gTransformer.circle(16).attr({ cx: plus1X, cy: cy, fill: COL.white, stroke: COL.black, 'stroke-width': 1.5 });
    gTransformer.line(plus1X - 5, cy, plus1X + 5, cy).stroke({ color: COL.black, width: 1.5 });
    gTransformer.line(plus1X, cy - 5, plus1X, cy + 5).stroke({ color: COL.black, width: 1.5 });

    // Residual skip line (over the top)
    var skipY = amY - 6;
    gTransformer.line(amX - 5, cy, amX - 5, skipY).stroke({ color: COL.black, width: 1 });
    gTransformer.line(amX - 5, skipY, plus1X, skipY).stroke({ color: COL.black, width: 1 });
    gTransformer.line(plus1X, skipY, plus1X, cy - 8).stroke({ color: COL.black, width: 1 });

    // Arrow from attention to ⊕
    gTransformer.line(amX + amW + 2, cy, plus1X - 8, cy).stroke({ color: COL.black, width: 1.2 });

    // First teal bar
    var tb1X = plus1X + 16;
    gTransformer.rect(10, amH * 0.9).attr({ x: tb1X, y: cy - amH * 0.45, fill: COL.teal, stroke: COL.tealStroke, 'stroke-width': 1.2, rx: 5 });
    gTransformer.line(plus1X + 8, cy, tb1X, cy).stroke({ color: COL.black, width: 1 });

    // Blue blocks
    var bbX = tb1X + 20;
    var bbCount = Math.min(n, Math.max(3, Math.floor(amH / 14)));
    for (var bi = 0; bi < bbCount; bi++) {
      var by = cy - amH * 0.4 + (amH * 0.8) * (bi / (bbCount - 1));
      gTransformer.rect(18, 10).attr({ x: bbX, y: by - 5, fill: COL.blue, stroke: COL.blueStroke, 'stroke-width': 1, rx: 4 });
      gTransformer.line(tb1X + 10, cy, bbX, by).stroke({ color: COL.black, width: 0.7 });
    }

    // Second ⊕
    var plus2X = bbX + 30;
    gTransformer.circle(16).attr({ cx: plus2X, cy: cy, fill: COL.white, stroke: COL.black, 'stroke-width': 1.5 });
    gTransformer.line(plus2X - 5, cy, plus2X + 5, cy).stroke({ color: COL.black, width: 1.5 });
    gTransformer.line(plus2X, cy - 5, plus2X, cy + 5).stroke({ color: COL.black, width: 1.5 });

    // Second residual skip
    var skip2Y = amY - 6;
    gTransformer.line(tb1X + 5, cy, tb1X + 5, skip2Y - 8).stroke({ color: COL.black, width: 1 });
    gTransformer.line(tb1X + 5, skip2Y - 8, plus2X, skip2Y - 8).stroke({ color: COL.black, width: 1 });
    gTransformer.line(plus2X, skip2Y - 8, plus2X, cy - 8).stroke({ color: COL.black, width: 1 });

    // Arrows from blue blocks to second ⊕
    for (var bi2 = 0; bi2 < bbCount; bi2++) {
      var by2 = cy - amH * 0.4 + (amH * 0.8) * (bi2 / (bbCount - 1));
      gTransformer.line(bbX + 18, by2, plus2X - 8, cy).stroke({ color: COL.black, width: 0.7 });
    }

    // Second teal bar
    var tb2X = plus2X + 16;
    gTransformer.rect(10, amH * 0.9).attr({ x: tb2X, y: cy - amH * 0.45, fill: COL.teal, stroke: COL.tealStroke, 'stroke-width': 1.2, rx: 5 });
    gTransformer.line(plus2X + 8, cy, tb2X, cy).stroke({ color: COL.black, width: 1 });

    // Arrow between layers
    if (li < k - 1) {
      var nextCy = tfY + 10 + (li + 1) * layerH + (layerH - 8) / 2;
      gTransformer.line(tb2X + 5, cy + amH * 0.45, tb2X + 5, nextCy - amH * 0.45 - 4).stroke({ color: COL.black, width: 1, 'stroke-dasharray': '3,2' });
    }
  }
}

drawTransformerBlock(1);

// ── (× K) annotation ──
var kLabel = gBg.text('(× K)').attr({ x: 510, y: midY - 8, 'font-size': 13, 'font-family': 'sans-serif', 'text-anchor': 'middle', fill: COL.black, 'font-style': 'italic' });
// Ellipsis dots
gBg.circle(4).attr({ cx: 505, cy: midY + 8, fill: COL.black });
gBg.circle(4).attr({ cx: 515, cy: midY + 8, fill: COL.black });
gBg.circle(4).attr({ cx: 525, cy: midY + 8, fill: COL.black });

// Arrow from transformer to (×K) area
gBg.line(tfX + tfW + 2, midY, 498, midY).stroke({ color: COL.black, width: 1.5 });
gBg.polygon('498,' + (midY - 4) + ' 505,' + midY + ' 498,' + (midY + 4)).fill(COL.black);

// Arrow from (×K) to Linear+softmax
gBg.line(532, midY, 565, midY).stroke({ color: COL.black, width: 1.5 });
gBg.polygon('565,' + (midY - 4) + ' 572,' + midY + ' 565,' + (midY + 4)).fill(COL.black);

// ── Linear + softmax blocks ──
var lsX = 580, lsW = 60, lsH = 22;
var lsGroup = gRight.group();
targets.forEach(function(t, i) {
  var y = rowY(i);
  var r = lsGroup.rect(lsW, lsH).attr({ x: lsX, y: y - lsH / 2, fill: COL.teal, stroke: COL.tealStroke, 'stroke-width': 1.5, rx: 10 });
  r.css('cursor', 'pointer');
  r.on('click', function() {
    showPopup('Linear + Softmax (position ' + i + ')', 'This layer projects the final hidden state at position ' + i + ' onto the vocabulary and applies softmax to produce a probability distribution over all tokens. The highest-probability token is the model\'s prediction for the next token after "' + tokens[i] + '".');
  });
  r.on('mousemove', function(e) { showTooltip('Linear + softmax for position ' + i, e); });
  r.on('mouseleave', function() { hideTooltip(); });
});

// Branching arrows from transformer output to each softmax block
gBg.line(572, midY, 576, midY).stroke({ color: COL.black, width: 1.2 });
gBg.line(576, rowY(0), 576, rowY(6)).stroke({ color: COL.black, width: 1.2 });
for (var i = 0; i < n; i++) {
  gBg.line(576, rowY(i), lsX - 2, rowY(i)).stroke({ color: COL.black, width: 1 });
  gBg.polygon((lsX - 2) + ',' + (rowY(i) - 3) + ' ' + (lsX + 2) + ',' + rowY(i) + ' ' + (lsX - 2) + ',' + (rowY(i) + 3)).fill(COL.black);
}

// ── Probability rows + target labels ──
var probX = 660, probBoxW = 16, probBoxH = 18, probGap = 2;
var probGroup = gRight.group();
targets.forEach(function(t, i) {
  var y = rowY(i);
  // Arrow from softmax to prob row
  probGroup.line(lsX + lsW + 2, y, probX - 4, y).stroke({ color: COL.black, width: 1 });
  probGroup.polygon((probX - 4) + ',' + (y - 3) + ' ' + probX + ',' + y + ' ' + (probX - 4) + ',' + (y + 3)).fill(COL.black);

  // 3 boxes, dotted gap, 2 boxes
  for (var b = 0; b < 3; b++) {
    probGroup.rect(probBoxW, probBoxH).attr({ x: probX + b * (probBoxW + probGap), y: y - probBoxH / 2, fill: COL.blue, stroke: COL.blueStroke, 'stroke-width': 0.8 });
  }
  // Dotted ellipsis
  var dotX = probX + 3 * (probBoxW + probGap) + 8;
  probGroup.circle(3).attr({ cx: dotX, cy: y, fill: COL.black });
  probGroup.circle(3).attr({ cx: dotX + 8, cy: y, fill: COL.black });
  probGroup.circle(3).attr({ cx: dotX + 16, cy: y, fill: COL.black });
  // Dotted lines above and below dots
  probGroup.line(dotX - 6, y - probBoxH / 2, dotX + 22, y - probBoxH / 2).stroke({ color: COL.blueStroke, width: 0.8, 'stroke-dasharray': '2,3' });
  probGroup.line(dotX - 6, y + probBoxH / 2, dotX + 22, y + probBoxH / 2).stroke({ color: COL.blueStroke, width: 0.8, 'stroke-dasharray': '2,3' });

  // 2 more boxes after gap
  var afterX = dotX + 28;
  for (var b2 = 0; b2 < 2; b2++) {
    probGroup.rect(probBoxW, probBoxH).attr({ x: afterX + b2 * (probBoxW + probGap), y: y - probBoxH / 2, fill: COL.blue, stroke: COL.blueStroke, 'stroke-width': 0.8 });
  }

  // Target label
  probGroup.text(t).attr({ x: afterX + 2 * (probBoxW + probGap) + 8, y: y + 5, 'font-size': 12, 'font-family': 'sans-serif', fill: COL.black });
});

// ── Rotated vocabulary labels ──
var vocabLabels = ['a', 'aardvark', 'abacus', '…', 'zero', 'zeta'];
var vocabX = probX;
var vocabY = rowY(6) + probBoxH / 2 + 8;
vocabLabels.forEach(function(v, vi) {
  var vx = vocabX + vi * 22;
  var t = gRight.text(v).attr({ x: vx, y: vocabY, 'font-size': 9, 'font-family': 'sans-serif', fill: COL.black, 'text-anchor': 'end' });
  t.transform({ rotate: -90, ox: vx, oy: vocabY });
});

// ── Click interactions on transformer blocks ──
var tfRect = gTransformer.rect(tfW, tfH).attr({ x: tfX, y: tfY, fill: 'transparent', stroke: 'none' });
tfRect.css('cursor', 'pointer');
tfRect.on('click', function() {
  showPopup('Transformer with Masked Attention', 'Each layer applies causal (masked) self-attention so position i can only attend to positions ≤ i, then adds the residual input. This is repeated K times. The causal mask ensures no position sees future tokens, enabling parallel training while preserving autoregressive structure.');
});
tfRect.on('mousemove', function(e) { showTooltip('Click to learn about the transformer block', e); });
tfRect.on('mouseleave', function() { hideTooltip(); });

// Embedding container click
var embRect = gBg.rect(100, 380).attr({ x: 62, y: 48, fill: 'transparent', stroke: 'none' });
embRect.css('cursor', 'pointer');
embRect.on('click', function() {
  showPopup('Word Embeddings', 'Each input token is mapped to a dense vector (embedding) that encodes its semantic identity. These vectors are the initial representations fed into the transformer. The same token always gets the same embedding vector.');
});
embRect.on('mousemove', function(e) { showTooltip('Click to learn about word embeddings', e); });
embRect.on('mouseleave', function() { hideTooltip(); });

// ── K layers slider ──
var currentK = 1;
function update_kLayers(v) {
  currentK = v;
  drawTransformerBlock(v);
  kLabel.text('(× ' + v + ')');
  // Re-add click handler on new transformer rect
  var newRect = gTransformer.rect(tfW, tfH).attr({ x: tfX, y: tfY, fill: 'transparent', stroke: 'none' });
  newRect.css('cursor', 'pointer');
  newRect.on('click', function() {
    showPopup('Transformer with Masked Attention (K=' + v + ')', 'This block shows ' + v + ' stacked layer' + (v > 1 ? 's' : '') + '. Each layer applies causal masked self-attention (position i attends only to positions ≤ i) followed by a residual addition. Depth refines representations without ever letting a position see future tokens.');
  });
  newRect.on('mousemove', function(e) { showTooltip(v + ' masked-attention layer' + (v > 1 ? 's' : ''), e); });
  newRect.on('mouseleave', function() { hideTooltip(); });
}

// ── Trace animation ──
var traceActive = false;
function trigger_traceYourself() {
  if (traceActive) return;
  traceActive = true;
  gOverlay.clear();

  var idx = 6; // 'let' → 'yourself'
  var y = rowY(idx);

  // Highlight path: embedding → transformer → softmax → prob row
  var pathPoints = [
    [76, y], [165, y], [tfX, y], [tfX + tfW, y], [576, y], [lsX, y], [lsX + lsW, y], [probX, y], [probX + 130, y]
  ];

  // Dim everything else
  var dimRect = gOverlay.rect(W, H).attr({ x: 0, y: 0, fill: '#fff', opacity: 0 });
  dimRect.animate(600).attr({ opacity: 0.55 });

  // Draw highlight path
  var hlLine = gOverlay.polyline(pathPoints.map(function(p) { return p[0] + ',' + p[1]; }).join(' '))
    .fill('none').stroke({ color: COL.highlight, width: 3.5, linecap: 'round' });
  var len = hlLine.length();
  hlLine.attr({ 'stroke-dasharray': len, 'stroke-dashoffset': len });
  hlLine.animate(2000).attr({ 'stroke-dashoffset': 0 });

  // Highlight the target label
  var hlText = gOverlay.text('yourself').attr({ x: probX + 138, y: y + 5, 'font-size': 14, 'font-family': 'sans-serif', fill: COL.highlight, 'font-weight': 'bold', opacity: 0 });
  hlText.animate(800).delay(1800).attr({ opacity: 1 });

  // Annotation
  var annText = gOverlay.text('Causal mask: only tokens ≤ "let" contribute').attr({ x: 300, y: y - 25, 'font-size': 11, 'font-family': 'sans-serif', fill: COL.highlight, 'font-weight': 'bold', opacity: 0, 'text-anchor': 'middle' });
  annText.animate(600).delay(2200).attr({ opacity: 1 });

  // Clear after 5 seconds
  setTimeout(function() {
    gOverlay.clear();
    traceActive = false;
  }, 5500);
}

// ── Demo steps ──
var steps = [
  {
    title: 'The left-to-right pipeline',
    narration: 'Input tokens become embeddings, pass through the masked-attention transformer block, and each position\'s output is mapped by Linear + softmax to a probability row over the vocabulary. Click any block to read its role.',
    state: { kLayers: 1 }
  },
  {
    title: 'Depth is repeated masking',
    narration: 'Drag K upward: the compact (× K) symbol unfolds into K stacked masked-attention + residual stages. Every layer applies the same causal rule, so depth refines representations without ever letting a position see future tokens.',
    state: { kLayers: 4 }
  },
  {
    title: 'Predicting "yourself"',
    narration: 'Collapse back to K=1 and run the trace: the prefix up to "let" flows through masked attention and residual adds into the final Linear + softmax, lighting up the bottom probability row labeled "yourself". The mask prevents any token after "let" from contributing.',
    state: { kLayers: 1 }
  }
];
var currentStep = 0;

function applyStep(idx) {
  currentStep = idx;
  var s = steps[idx];
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (idx + 1) + '/' + steps.length;
  // Apply state
  if (s.state.kLayers !== undefined) {
    document.getElementById('kLayersInput').value = s.state.kLayers;
    document.getElementById('kLayersVal').value = s.state.kLayers;
    update_kLayers(s.state.kLayers);
  }
  if (idx === 2) {
    setTimeout(function() { trigger_traceYourself(); }, 400);
  }
}

function nextStep() { applyStep(Math.min(currentStep + 1, steps.length - 1)); }
function prevStep() { applyStep(Math.max(currentStep - 1, 0)); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

