    // Lower-triangular lines inside attention matrix
    var lineCount = Math.min(n, Math.max(3, Math.floor(amH / 14)));
    for (var i = 0; i < lineCount; i++) {
      for (var j = 0; j <= i; j++) {
        var y1 = amY + 6 + (amH - 12) * (i / Math.max(1, lineCount - 1));
        var y2 = amY + 6 + (amH - 12) * (j / Math.max(1, lineCount - 1));
        gTransformer.line(amX + 6, y1, amX + amW - 6, y2).stroke({ color: COL.orangeLine, width: 0.8, opacity: 0.65 });
      }
    }

    // First ⊕
    var plus1X = amX + amW + 32;
    gTransformer.circle(20).attr({ cx: plus1X, cy: cy, fill: COL.white, stroke: COL.black, 'stroke-width': 1.8 });
    gTransformer.line(plus1X - 6, cy, plus1X + 6, cy).stroke({ color: COL.black, width: 1.8 });
    gTransformer.line(plus1X, cy - 6, plus1X, cy + 6).stroke({ color: COL.black, width: 1.8 });

    // Residual skip line 1 (over the top of attention matrix)
    var skip1Y = amY - 10;
    gTransformer.line(amX - 8, cy, amX - 8, skip1Y).stroke({ color: COL.black, width: 1.5 });
    gTransformer.line(amX - 8, skip1Y, plus1X, skip1Y).stroke({ color: COL.black, width: 1.5 });
    gTransformer.line(plus1X, skip1Y, plus1X, cy - 10).stroke({ color: COL.black, width: 1.5 });
    // Arrowhead into ⊕
    gTransformer.polygon((plus1X - 3) + ',' + (cy - 14) + ' ' + (plus1X + 3) + ',' + (cy - 14) + ' ' + plus1X + ',' + (cy - 10)).fill(COL.black);

    // Arrow from attention to ⊕
    gTransformer.line(amX + amW + 2, cy, plus1X - 10, cy).stroke({ color: COL.black, width: 1.5 });
    gTransformer.polygon((plus1X - 14) + ',' + (cy - 3.5) + ' ' + (plus1X - 10) + ',' + cy + ' ' + (plus1X - 14) + ',' + (cy + 3.5)).fill(COL.black);

    // First teal bar
    var tb1X = plus1X + 22;
    gTransformer.rect(14, amH * 0.92).attr({ x: tb1X, y: cy - amH * 0.46, fill: COL.teal, stroke: COL.tealStroke, 'stroke-width': 1.5, rx: 7 });
    gTransformer.line(plus1X + 10, cy, tb1X, cy).stroke({ color: COL.black, width: 1.2 });

    // Blue blocks column (rounded rectangles)
    var bbX = tb1X + 32;
    var bbW = 26, bbH = 12;
    var bbCount = Math.min(n, Math.max(3, Math.floor(amH / 16)));
    for (var bi = 0; bi < bbCount; bi++) {
      var by = cy - amH * 0.4 + (amH * 0.8) * (bi / Math.max(1, bbCount - 1));
      gTransformer.rect(bbW, bbH).attr({ x: bbX, y: by - bbH / 2, fill: COL.blue, stroke: COL.blueStroke, 'stroke-width': 1.2, rx: 5 });
      // Connection line from teal bar to blue block
      gTransformer.line(tb1X + 14, cy, bbX, by).stroke({ color: COL.black, width: 0.8 });
    }

    // Second ⊕
    var plus2X = bbX + bbW + 32;
    gTransformer.circle(20).attr({ cx: plus2X, cy: cy, fill: COL.white, stroke: COL.black, 'stroke-width': 1.8 });
    gTransformer.line(plus2X - 6, cy, plus2X + 6, cy).stroke({ color: COL.black, width: 1.8 });
    gTransformer.line(plus2X, cy - 6, plus2X, cy + 6).stroke({ color: COL.black, width: 1.8 });

    // Residual skip line 2 (over the top of blue blocks)
    var skip2Y = amY - 10;
    gTransformer.line(tb1X + 7, cy, tb1X + 7, skip2Y - 10).stroke({ color: COL.black, width: 1.5 });
    gTransformer.line(tb1X + 7, skip2Y - 10, plus2X, skip2Y - 10).stroke({ color: COL.black, width: 1.5 });
    gTransformer.line(plus2X, skip2Y - 10, plus2X, cy - 10).stroke({ color: COL.black, width: 1.5 });
    gTransformer.polygon((plus2X - 3) + ',' + (cy - 14) + ' ' + (plus2X + 3) + ',' + (cy - 14) + ' ' + plus2X + ',' + (cy - 10)).fill(COL.black);

    // Arrows from blue blocks to second ⊕
    for (var bi2 = 0; bi2 < bbCount; bi2++) {
      var by2 = cy - amH * 0.4 + (amH * 0.8) * (bi2 / Math.max(1, bbCount - 1));
      gTransformer.line(bbX + bbW, by2, plus2X - 10, cy).stroke({ color: COL.black, width: 0.8 });
    }

    // Second teal bar
    var tb2X = plus2X + 22;
    gTransformer.rect(14, amH * 0.92).attr({ x: tb2X, y: cy - amH * 0.46, fill: COL.teal, stroke: COL.tealStroke, 'stroke-width': 1.5, rx: 7 });
    gTransformer.line(plus2X + 10, cy, tb2X, cy).stroke({ color: COL.black, width: 1.2 });

    // Arrow between layers
    if (li < k - 1) {
      var nextCy = tfY + 12 + (li + 1) * layerH + (layerH - 10) / 2;
      gTransformer.line(tb2X + 7, cy + amH * 0.46, tb2X + 7, nextCy - amH * 0.46 - 5).stroke({ color: COL.black, width: 1.2, 'stroke-dasharray': '4,3' });
    }
  }
}

